import{_ as e,o as a,c as n,a2 as o}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"Set up navigation","description":"Adjust the order and scope of the Space navigation.","frontmatter":{"title":"Set up navigation","description":"Adjust the order and scope of the Space navigation."},"headers":[],"relativePath":"en/spaces/navigation.md","filePath":"en/spaces/navigation.md","lastUpdated":1787319236000}'),s={name:"en/spaces/navigation.md"};function i(r,t,d,l,h,g){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="set-up-navigation" tabindex="-1">Set up navigation <a class="header-anchor" href="#set-up-navigation" aria-label="Permalink to &quot;Set up navigation&quot;">​</a></h1><p>A Space&#39;s sidebar shows three areas: <strong>Grids</strong>, <strong>Pages</strong>, and <strong>Flows</strong>. You can adjust their order and scope.</p><p>You&#39;ll find these settings under <strong>Space settings → General</strong>, in the <strong>Navigation</strong> section.</p><h2 id="order-of-sections" tabindex="-1">Order of sections <a class="header-anchor" href="#order-of-sections" aria-label="Permalink to &quot;Order of sections&quot;">​</a></h2><p>The setting is called <strong>Set section order</strong>:</p><blockquote><p><em>Decide the order in which pages and grids appear in the navigation.</em></p></blockquote><p>Two options:</p><table tabindex="0"><thead><tr><th>Choice</th><th>Order</th></tr></thead><tbody><tr><td><strong>Show grids first</strong></td><td>Grids, then Pages</td></tr><tr><td><strong>Show pages first</strong></td><td>Pages, then Grids</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Choose based on main usage</p><ul><li><strong>Grids first</strong> for Spaces mainly used to maintain data.</li><li><strong>Pages first</strong> for Spaces built mostly around <a href="/en/seiten/portal-veroeffentlichen">portals</a> or documentation — this puts the entry point at the top.</li></ul><p>This setting applies to <strong>everyone</strong> in the Space, not just you. Coordinate with others if several people work in it.</p></div><h2 id="number-of-visible-grids" tabindex="-1">Number of visible Grids <a class="header-anchor" href="#number-of-visible-grids" aria-label="Permalink to &quot;Number of visible Grids&quot;">​</a></h2><p>The setting is called <strong>Grids shown in navigation</strong>:</p><blockquote><p><em>Number of grids shown before collapsing</em></p></blockquote><p>The default is <strong>10</strong>. The rest are hidden behind <strong>Show more</strong> or <strong>Show less</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Set it lower for many Grids</p><p>If a Space has thirty Grids, the sidebar becomes unusably long. A value of five to eight keeps it manageable; the rest stays reachable via <em>Show more</em>.</p><p>Which Grids land in the visible group depends on their order in the navigation — so the most important ones should be at the top.</p></div><h2 id="what-appears-in-the-navigation-under-a-grid" tabindex="-1">What appears in the navigation under a Grid <a class="header-anchor" href="#what-appears-in-the-navigation-under-a-grid" aria-label="Permalink to &quot;What appears in the navigation under a Grid&quot;">​</a></h2><p>Under each Grid, the navigation is organized into:</p><ul><li><strong>Views</strong> — every representation of this Grid</li><li><strong>Forms</strong> — every input mask of this Grid</li></ul><p>Use <strong>Create</strong> to add a <strong>Create view</strong> or <strong>Create form</strong>.</p><h2 id="other-navigation-elements" tabindex="-1">Other navigation elements <a class="header-anchor" href="#other-navigation-elements" aria-label="Permalink to &quot;Other navigation elements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Element</th><th>Function</th></tr></thead><tbody><tr><td><strong>All Spaces</strong></td><td>Back to the Space overview</td></tr><tr><td><strong>Grids</strong> / <strong>Pages</strong> / <strong>Flows</strong></td><td>The three areas</td></tr><tr><td><strong>Show more</strong> / <strong>Show less</strong></td><td>Expands and collapses the Grid list</td></tr></tbody></table><h2 id="navigation-in-published-portals" tabindex="-1">Navigation in published portals <a class="header-anchor" href="#navigation-in-published-portals" aria-label="Permalink to &quot;Navigation in published portals&quot;">​</a></h2><p>For <a href="/en/seiten/was-sind-seiten">Pages</a> with sub-pages, there&#39;s a dedicated setting: <strong>Collapsible navigation</strong>. It only affects the presentation in the portal, not the Space navigation.</p><p>→ <a href="/en/seiten/seite-erstellen">Create and edit a page</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/spaces/einstellungen">Space settings</a></li><li><a href="/en/spaces/symbol-und-farbe">Icon, color, and category</a></li><li><a href="/en/erste-schritte/oberflaeche">The interface at a glance</a></li></ul>',25)])])}const u=e(s,[["render",i]]);export{c as __pageData,u as default};
